 81→		if _, err := parseAAPLRequest(make([]byte, n)); err == nil {
 82→			t.Errorf("长度 %d 的 AAPL 请求应当被拒绝", n)
 83→		}
 84→	}
 85→	// 不能因为越界切片 panic。
 86→	if _, err := parseAAPLRequest(nil); err == nil {
