102→// TestBuildAAPLResponseModelInfo 验证带 ModelString 的完整响应布局。
103→//
104→// ModelString 段：4 字节保留 0 + 4 字节**字节**长度 + UTF-16LE 字符串
105→// （Samba check_aapl 的写法：SIVAL(p,0,0); SIVAL(p+4,0,modellen)）。
106→func TestBuildAAPLResponseModelInfo(t *testing.T) {
107→	const model = "MacSamba"
108→	bitmap := aaplServerCaps | aaplVolumeCaps | aaplModelInfo
109→	serverCaps := aaplUnixBased | aaplSupportsReadDirAttr
110→
111→	got := buildAAPLResponse(bitmap, serverCaps, aaplSupportsFullSync, model)
112→
113→	wantLen := 16 + 8 + 8 + 8 + 2*len(model)
114→	if len(got) != wantLen {
115→		t.Fatalf("长度 = %d, 期望 %d", len(got), wantLen)
116→	}
117→	if v := aaplLE.Uint32(got[0:4]); v != aaplServerQuery {
118→		t.Errorf("CommandCode = %d, 期望 %d", v, aaplServerQuery)
119→	}
120→	if v := aaplLE.Uint32(got[4:8]); v != 0 {
121→		t.Errorf("Reserved = %#x, 期望 0", v)
122→	}
123→	if v := aaplLE.Uint64(got[8:16]); v != bitmap {
124→		t.Errorf("ReplyBitmap = %#x, 期望 %#x", v, bitmap)
125→	}
126→	if v := aaplLE.Uint64(got[16:24]); v != serverCaps {
127→		t.Errorf("ServerCapabilities = %#x, 期望 %#x", v, serverCaps)
128→	}
129→	if v := aaplLE.Uint64(got[24:32]); v != aaplSupportsFullSync {
130→		t.Errorf("VolumeCapabilities = %#x, 期望 %#x", v, aaplSupportsFullSync)
131→	}
132→	if v := aaplLE.Uint32(got[32:36]); v != 0 {
133→		t.Errorf("ModelString 段保留字段 = %#x, 期望 0", v)
134→	}
135→	if v := aaplLE.Uint32(got[36:40]); int(v) != 2*len(model) {
136→		t.Errorf("ModelString 长度 = %d, 期望 %d（UTF-16LE 字节数）", v, 2*len(model))
137→	}
138→	if want := wire.EncodeUTF16LE(model); !bytes.Equal(got[40:], want) {
139→		t.Errorf("ModelString = %x, 期望 %x", got[40:], want)
140→	}
141→}
