175→// TestAAPLContextWireRoundTrip 验证 AAPL context 能按 MS-SMB2 §2.2.13.2
176→// 的 create context 链格式编码并原样解回来（8 字节对齐是历史上的老坑）。
177→func TestAAPLContextWireRoundTrip(t *testing.T) {
178→	in := []wire.CreateContext{{Name: wire.CreateContextAAPL, Data: appleSpecRequest}}
179→	raw, err := wire.AppendCreateContexts(nil, in)
180→	if err != nil {
181→		t.Fatalf("AppendCreateContexts: %v", err)
182→	}
183→	out, err := wire.ParseCreateContexts(raw)
184→	if err != nil {
185→		t.Fatalf("ParseCreateContexts: %v", err)
186→	}
187→	data, ok := wire.FindCreateContext(out, wire.CreateContextAAPL)
188→	if !ok {
189→		t.Fatal("解析结果里找不到 AAPL context")
190→	}
191→	if !bytes.Equal(data, appleSpecRequest) {
192→		t.Errorf("往返后 Data = %x, 期望 %x", data, appleSpecRequest)
193→	}
194→}
