// 里面带 FinderInfo 与资源派生 —— 与 vfs 的 AFP_Resource 实现使用同一格式。
func writeAppleDouble(t *testing.T, path string, fi [vfs.FinderInfoSize]byte, rsrc []byte) {
	t.Helper()

	ad := vfs.NewAppleDouble()
	ad.SetFinderInfo(fi)
	ad.SetResource(rsrc)
