 53→// 名字长度与分布会影响排序与匹配的开销。
 54→func buildBandDir(tb testing.TB, n int) string {
 55→	tb.Helper()
 56→	root := tb.TempDir()
 57→	bands := filepath.Join(root, "bands")
 58→	if err := os.Mkdir(bands, 0o755); err != nil {
 59→		tb.Fatal(err)
 60→	}
 61→	for i := 0; i < n; i++ {
 62→		p := filepath.Join(bands, fmt.Sprintf("%x", i))
 63→		if err := os.WriteFile(p, nil, 0o644); err != nil {
 64→			tb.Fatal(err)
 65→		}
 66→	}
 67→	return root
 68→}
 69→
 70→// enumerateAll 模拟客户端把一个目录分页枚举到底，返回总条数。
 71→func enumerateAll(tb testing.TB, fs *LocalFS, dir string, page int) int {
 72→	tb.Helper()
 73→	h, _, err := fs.Open(&OpenRequest{
 74→		Path: dir, Flags: OpenRead | OpenDirectory, Disposition: OpenExisting,
 75→	})
 76→	if err != nil {
 77→		tb.Fatal(err)
 78→	}
 79→	defer func() { _ = h.Close() }()
 80→
 81→	total := 0
 82→	for {
 83→		batch, err := h.ReadDir("*", false, page)
 84→		total += len(batch)
 85→		if err == io.EOF {
 86→			return total
 87→		}
 88→		if err != nil {
 89→			tb.Fatal(err)
 90→		}
 91→		if len(batch) == 0 {
 92→			return total
 93→		}
 94→	}
 95→}
 96→
 97→func benchReadDir(b *testing.B, n, page int) {
 98→	root := buildBandDir(b, n)
 99→	fs, err := NewLocalFS(LocalConfig{Root: root, CaseInsensitive: true})
100→	if err != nil {
101→		b.Fatal(err)
102→	}
103→	defer func() { _ = fs.Close() }()
104→
105→	b.ResetTimer()
106→	for i := 0; i < b.N; i++ {
107→		got := enumerateAll(b, fs, "bands", page)
108→		// +2 是 "." 和 ".."
109→		if got != n+2 {
110→			b.Fatalf("枚举到 %d 条, want %d", got, n+2)
111→		}
112→	}
113→}
114→
115→// 每批 100 条大致对应真实客户端在 64KiB 输出缓冲下的批量。
116→func BenchmarkReadDir1k(b *testing.B)  { benchReadDir(b, 1_000, 100) }
117→func BenchmarkReadDir10k(b *testing.B) { benchReadDir(b, 10_000, 100) }
118→
119→func BenchmarkReadDir50k(b *testing.B) {
120→	if testing.Short() {
121→		b.Skip("建 5 万个文件较慢，-short 下跳过")
122→	}
123→	benchReadDir(b, 50_000, 100)
124→}
125→
126→// BenchmarkReadDirFirstPage 单独量**首个** QUERY_DIRECTORY 的延迟。
127→//
128→// 这是最关键的指标：快照是在第一次调用时一次性建立的，
129→// 如果这里要好几秒，客户端会认为服务器无响应。
130→func BenchmarkReadDirFirstPage(b *testing.B) {
131→	if testing.Short() {
132→		b.Skip("建 5 万个文件较慢，-short 下跳过")
133→	}
134→	root := buildBandDir(b, 50_000)
135→	fs, err := NewLocalFS(LocalConfig{Root: root, CaseInsensitive: true})
136→	if err != nil {
137→		b.Fatal(err)
138→	}
139→	defer func() { _ = fs.Close() }()
140→
141→	b.ResetTimer()
142→	for i := 0; i < b.N; i++ {
143→		h, _, err := fs.Open(&OpenRequest{
144→			Path: "bands", Flags: OpenRead | OpenDirectory, Disposition: OpenExisting,
145→		})
146→		if err != nil {
147→			b.Fatal(err)
148→		}
149→		if _, err := h.ReadDir("*", false, 100); err != nil && err != io.EOF {
150→			b.Fatal(err)
151→		}
152→		_ = h.Close()
153→	}
154→}
155→
156→// TestReadDirLargeDirCorrectness 是 benchmark 的正确性对照：
157→// 大目录下分页枚举必须**不重不漏**。
158→//
159→// 单独写一个的理由：翻页游标的 off-by-one 在小目录上很难暴露，
160→// 而 Time Machine 恰恰跑在几万条的目录上。
161→func TestReadDirLargeDirCorrectness(t *testing.T) {
162→	if testing.Short() {
163→		t.Skip("-short 下跳过")
164→	}
165→	const n = 5_000
166→	root := buildBandDir(t, n)
167→	fs, err := NewLocalFS(LocalConfig{Root: root, CaseInsensitive: true})
168→	if err != nil {
169→		t.Fatal(err)
170→	}
171→	defer func() { _ = fs.Close() }()
172→
173→	h, _, err := fs.Open(&OpenRequest{
174→		Path: "bands", Flags: OpenRead | OpenDirectory, Disposition: OpenExisting,
175→	})
176→	if err != nil {
177→		t.Fatal(err)
178→	}
179→	defer func() { _ = h.Close() }()
180→
181→	seen := make(map[string]int, n)
182→	for {
183→		batch, err := h.ReadDir("*", false, 97) // 故意用质数批量，制造边界
184→		for _, e := range batch {
185→			seen[e.Name]++
186→		}
187→		if err == io.EOF {
188→			break
189→		}
190→		if err != nil {
191→			t.Fatal(err)
192→		}
193→		if len(batch) == 0 {
194→			break
195→		}
196→	}
197→
198→	if len(seen) != n+2 {
199→		t.Errorf("枚举到 %d 个不同条目, want %d（含 . 与 ..）", len(seen), n+2)
200→	}
201→	for name, c := range seen {
202→		if c != 1 {
203→			t.Errorf("条目 %q 出现了 %d 次，应恰好 1 次", name, c)
204→		}
205→	}
206→	for i := 0; i < n; i++ {
207→		if _, ok := seen[fmt.Sprintf("%x", i)]; !ok {
208→			t.Fatalf("条目 %x 漏了", i)
209→		}
210→	}
211→}
212→

