427→// aaplDirAttrSource 在一次 QUERY_DIRECTORY 内为每条目录项取 Apple 元数据。
428→//
429→// 每条目录项都要向后端多问一次（LocalFS 里是 lstat + getxattr + stat "._name"），
430→// 这是 readdir_attr 的固有代价；Samba 同样是逐条 fetch。所以它**只在协商成功后**
431→// 才启用，普通 Windows/Linux 客户端不会付这个钱。
432→type aaplDirAttrSource struct {
433→	meta vfs.AppleMetadata
434→	// dir 是被枚举目录相对共享根的路径（'/' 分隔，空串表示共享根）。
435→	dir string
436→	// maxAccess 是树级别的最大访问掩码。
437→	//
438→	// Samba 用 smbd_calculate_access_mask_fsp(SEC_FLAG_MAXIMUM_ALLOWED) 逐文件算，
439→	// 那是基于宿主 ACL 的。本项目的授权依据只有配置文件（AGENTS.md §1.1 C8：
440→	// 不读宿主 ACL 做访问判定），因此同一棵树上所有条目取同一个值。
441→	maxAccess uint32
442→}
443→
444→// newAAPLDirAttrSource 在本连接协商过 readdir_attr、且后端能提供 Apple 元数据时
445→// 返回取值器；否则返回 nil，调用方据此退化为标准布局。
446→func newAAPLDirAttrSource(ctx *Context, open *Open, class wire.FileInfoClass) *aaplDirAttrSource {
447→	// Samba 只在 SMB_FIND_ID_BOTH_DIRECTORY_INFO 上改布局，其余 class 原样。
448→	// macOS 用的正是这个 class。
449→	if class != wire.FileIdBothDirectoryInformation {
450→		return nil
451→	}
452→	if !ctx.Conn.AAPLReaddirAttr() {
453→		return nil
454→	}
455→	meta, ok := ctx.Tree.FS().(vfs.AppleMetadata)
456→	if !ok {
457→		return nil
458→	}
459→	return &aaplDirAttrSource{
460→		meta:      meta,
461→		dir:       open.Path,
462→		maxAccess: uint32(maximalAccessFor(ctx.Tree)),
463→	}
464→}
