466→// entry 取一条目录项的 Apple 扩展数据。后端出错时退化成「没有元数据」，
467→// 绝不让一个坏文件毁掉整批枚举（同 vfs_fruit：非致命错误照样返回该条目）。
468→func (s *aaplDirAttrSource) entry(e *vfs.DirEntry) aaplDirAttr {
469→	a := aaplDirAttr{MaxAccess: s.maxAccess}
470→	isDir := e.Attr.FileAttributes&vfs.FileAttributeDirectory != 0
471→
472→	var full [vfs.FinderInfoSize]byte
473→	var hasMeta bool
474→	if p, ok := s.childPath(e.Name); ok {
475→		fi, rsrc, err := s.meta.AppleInfo(p)
476→		if err == nil {
477→			full = fi
478→			// vfs.AppleInfo 对「没有 Apple 元数据」与「有但全零」返回同样的结果，
479→			// 只能用全零近似判定。差异仅体现在 date added 是真实时间还是
480→			// AD_DATE_START，Finder 不据此做任何功能性决策。
481→			//
482→			// TODO: 待 vfs 层能区分（AppleInfo 多返回一个 hasMeta，
483→			// 或缺元数据时返回 ErrNotFound）后改为精确判定。
484→			hasMeta = full != [vfs.FinderInfoSize]byte{}
485→			// 目录没有资源派生；Samba 也只对文件取 rfork_size。
486→			if !isDir && rsrc > 0 {
487→				a.RsrcSize = uint64(rsrc)
488→			}
489→		}
